const upsertWAGroup = `-- name: UpsertWAGroup :one
insert into wa_groups (jid, name, kind, branch, members, read_enabled)
values ($1, $2, $3, $4, $5, $6)
on conflict (jid) do update set name = coalesce(nullif(excluded.name, ''), wa_groups.name), members = coalesce(excluded.members, wa_groups.members)
returning id, jid, name, kind, branch, members, read_enabled, kind_manual
`

type UpsertWAGroupParams struct {
	Jid         *string `json:"jid"`
	Name        *string `json:"name"`
	Kind        *string `json:"kind"`
	Branch      *string `json:"branch"`
	Members     *int32  `json:"members"`
	ReadEnabled bool    `json:"read_enabled"`
}

func (q *Queries) UpsertWAGroup(ctx context.Context, arg UpsertWAGroupParams) (WaGroup, error) {
	row := q.db.QueryRow(ctx, upsertWAGroup,
		arg.Jid,
		arg.Name,
		arg.Kind,
		arg.Branch,
		arg.Members,
		arg.ReadEnabled,
	)
	var i WaGroup
	err := row.Scan(
		&i.ID,
		&i.Jid,
		&i.Name,
		&i.Kind,
		&i.Branch,
		&i.Members,
		&i.ReadEnabled,
		&i.KindManual,
	)
	return i, err
}

const upsertWANumber = `-- name: UpsertWANumber :exec
insert into wa_numbers (wa_number, sales_id, label, transport, state, user_id, session_id)
values ($1, $2, $3, $4, $5, $6, $1)
on conflict (wa_number) do update set sales_id = excluded.sales_id, label = excluded.label, transport = excluded.transport,
  user_id = coalesce(excluded.user_id, wa_numbers.user_id)
`

type UpsertWANumberParams struct {
	WaNumber  string     `json:"wa_number"`
	SalesID   *uuid.UUID `json:"sales_id"`
	Label     *string    `json:"label"`
	Transport string     `json:"transport"`
	State     string     `json:"state"`
	UserID    *uuid.UUID `json:"user_id"`
}

func (q *Queries) UpsertWANumber(ctx context.Context, arg UpsertWANumberParams) error {
	_, err := q.db.Exec(ctx, upsertWANumber,
		arg.WaNumber,
		arg.SalesID,
		arg.Label,
		arg.Transport,
		arg.State,
		arg.UserID,
	)
	return err
}

const userThreadPins = `-- name: UserThreadPins :many
select conv, pinned_at from chat_thread_pins where user_id = $1 order by pinned_at desc
`

type UserThreadPinsRow struct {
	Conv     string    `json:"conv"`
	PinnedAt time.Time `json:"pinned_at"`
}

// The chats a person pinned to the top of their list, last pinned first.
func (q *Queries) UserThreadPins(ctx context.Context, userID uuid.UUID) ([]UserThreadPinsRow, error) {
	rows, err := q.db.Query(ctx, userThreadPins, userID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []UserThreadPinsRow{}
	for rows.Next() {
		var i UserThreadPinsRow
		if err := rows.Scan(&i.Conv, &i.PinnedAt); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}
